window.GeometryPlans = [{"id":"P1-01","grade":1,"title":{"en":"Paths that bend and paths that go straight","pt":"Caminhos curvos e caminhos retos"},"gap":{"en":"Adds a spatial movement lesson before formal shape names.","pt":"Acrescenta uma vivência espacial antes dos nomes formais."},"source":"J1","ready":{"en":"Follow a short route and describe where it begins.","pt":"Seguir um percurso curto e indicar onde começa."},"materials":{"en":"Yarn, paper and broad crayons.","pt":"Fio de lã, papel e giz de cera grosso."},"aim":{"en":"Recognise straight and curved paths; distinguish an open path from a closed one.","pt":"Reconhecer caminhos retos e curvos; distinguir um caminho aberto de um fechado."},"teaching":{"en":"A straight path keeps one direction. A curved path changes direction. Either kind can be open; a closed boundary returns to its start and surrounds a region. Do not require degrees or formal definitions.","pt":"Um caminho reto mantém uma direção. Um caminho curvo muda de direção. Ambos podem ser abertos; um contorno fechado volta ao início e cerca uma região. Não exija graus nem definições formais."},"flow":[{"en":"5 min · Recall a walk to the door. Trace its route in the air.","pt":"5 min · Lembre um passeio até a porta. Trace o caminho no ar."},{"en":"10 min · Lay a straight yarn path and a curved one. Move a counter along each, then describe what changes.","pt":"10 min · Monte um caminho reto e outro curvo com lã. Mova uma ficha sobre cada um e descreva o que muda."},{"en":"10 min · Make an open curve, then close it. Draw both; place a counter inside and another outside the closed boundary.","pt":"10 min · Faça uma curva aberta e depois feche-a. Desenhe ambas; ponha uma ficha dentro e outra fora do contorno fechado."},{"en":"5 min · Show a new path and ask whether it closes. Recall the distinction tomorrow with a different shape.","pt":"5 min · Mostre um caminho novo e pergunte se fecha. Retome amanhã com outra forma."}],"practice":[{"q":{"en":"Does a straight segment return to its start?","pt":"Um segmento reto volta ao início?"},"a":{"en":"No; its two endpoints are different.","pt":"Não; suas duas extremidades são diferentes."}},{"q":{"en":"Can a curved path stay open?","pt":"Um caminho curvo pode ficar aberto?"},"a":{"en":"Yes, such as a U-shaped path. Curved does not mean closed.","pt":"Sim, como um caminho em U. Curvo não significa fechado."}},{"q":{"en":"Make a closed path with straight pieces.","pt":"Faça um caminho fechado com partes retas."},"a":{"en":"A triangle or rectangle works: the last piece meets the first.","pt":"Um triângulo ou retângulo serve: a última parte encontra a primeira."}}],"observe":{"en":"Ask the child to explain inside and outside using their own boundary.","pt":"Peça à criança para explicar dentro e fora usando seu contorno."},"support":{"en":"Move a toy or finger instead of walking; use a raised yarn boundary.","pt":"Mova um brinquedo ou dedo em vez de caminhar; use um contorno de lã em relevo."},"extend":{"en":"Combine straight and curved parts in one closed design.","pt":"Combine partes retas e curvas em um desenho fechado."},"links":["P2-01.html"],"diagram":"paths","duration":30},{"id":"P2-01","grade":2,"title":{"en":"A pattern across the fold","pt":"Um padrão do outro lado da dobra"},"gap":{"en":"Deepens early symmetry through matching distance and position.","pt":"Aprofunda a simetria inicial por distância e posição correspondentes."},"source":"J2","ready":{"en":"Distinguish two sides of a paper fold.","pt":"Distinguir os dois lados de uma dobra."},"materials":{"en":"Paper, washable paint or counters, crayons.","pt":"Papel, tinta lavável ou fichas, giz de cera."},"aim":{"en":"Create and check a reflected pattern without counting symmetry axes formally.","pt":"Criar e conferir um padrão refletido sem contar eixos formalmente."},"teaching":{"en":"A reflection pairs each point with one equally far from the fold on the opposite side. A point on the fold stays there. Matching colours alone does not make a reflection.","pt":"Uma reflexão associa cada ponto a outro igualmente distante da dobra, no lado oposto. Um ponto na dobra fica no mesmo lugar. Cores iguais, sozinhas, não garantem reflexão."},"flow":[{"en":"5 min · Fold and unfold paper; trace the crease.","pt":"5 min · Dobre e abra o papel; marque o vinco."},{"en":"10 min · Place three paint dots on one side and fold to print partners, or place counter pairs at matching distances.","pt":"10 min · Faça três pintas de tinta de um lado e dobre para imprimir seus pares, ou posicione pares de fichas a distâncias iguais."},{"en":"10 min · Draw a new pattern with one deliberate misplaced partner. Ask a friend to repair it by folding.","pt":"10 min · Desenhe um padrão com um par fora do lugar. Peça a alguém para corrigi-lo dobrando."},{"en":"5 min · Explain why a dot on the crease needs no second dot. Next day, repeat with a sloping fold.","pt":"5 min · Explique por que uma pinta no vinco não precisa de outra. No dia seguinte, repita com dobra inclinada."}],"practice":[{"q":{"en":"Three dots lie off the fold. How many partners are needed?","pt":"Três pintas estão fora da dobra. Quantos pares novos são necessários?"},"a":{"en":"Three new dots, giving six altogether.","pt":"Três pintas novas, totalizando seis."}},{"q":{"en":"A dot is two counter-widths from the fold. Where is its partner?","pt":"Uma pinta fica a duas larguras de ficha da dobra. Onde fica seu par?"},"a":{"en":"Opposite it, two counter-widths away on the other side.","pt":"Em frente, a duas larguras de ficha no outro lado."}},{"q":{"en":"Does tilting the paper destroy the reflection?","pt":"Inclinar o papel destrói a reflexão?"},"a":{"en":"No; the pairs still match when folded.","pt":"Não; os pares ainda coincidem ao dobrar."}}],"observe":{"en":"Check that the learner tests coincidence rather than guessing by colour.","pt":"Verifique se testa a coincidência em vez de adivinhar pela cor."},"support":{"en":"Use large tactile counter pairs; a partner may fold the paper.","pt":"Use pares grandes de fichas táteis; outra pessoa pode dobrar o papel."},"extend":{"en":"Place one dot on the fold and three off it: seven dots make the complete design.","pt":"Coloque uma pinta na dobra e três fora: sete pintas formam o desenho completo."},"links":["P3-01.html"],"diagram":"mirror","duration":30},{"id":"P3-01","grade":3,"title":{"en":"A plan of our reading corner","pt":"Uma planta do nosso canto de leitura"},"gap":{"en":"Connects practical measurement to position, plan views and scale.","pt":"Liga medidas práticas à posição, vista de cima e escala."},"source":"J3","ready":{"en":"Measure short lengths in centimetres and count equal groups.","pt":"Medir comprimentos curtos em centímetros e contar grupos iguais."},"materials":{"en":"Tape measure, squared paper and toy furniture.","pt":"Trena, papel quadriculado e móveis de brinquedo."},"aim":{"en":"Distinguish a top view from a front view; use a simple declared scale.","pt":"Distinguir vista de cima de vista frontal; usar uma escala simples declarada."},"teaching":{"en":"A plan looks down from above. Use 1 paper square for 10 cm in this model. A rectangular 60 cm by 40 cm tabletop becomes 6 by 4 squares. A drawing length and the real length need different unit labels.","pt":"Uma planta olha de cima. Use 1 quadradinho para 10 cm neste modelo. Uma mesa de 60 cm por 40 cm vira 6 por 4 quadradinhos. A medida do desenho e a real precisam de unidades distintas."},"flow":[{"en":"5 min · Look at a toy from above and from the side. Say which view shows its footprint.","pt":"5 min · Olhe um brinquedo de cima e de lado. Diga qual vista mostra o espaço que ocupa no chão."},{"en":"15 min · Measure a tabletop or use 60 cm by 40 cm. Build its 6 by 4 square plan and add a scale key.","pt":"15 min · Meça uma mesa ou use 60 cm por 40 cm. Faça uma planta de 6 por 4 quadradinhos e acrescente a legenda da escala."},{"en":"5 min · Put a 20 cm square cushion on the model. Draw its 2 by 2 square footprint in two possible positions.","pt":"5 min · Ponha uma almofada quadrada de 20 cm no modelo. Desenhe sua marca de 2 por 2 quadradinhos em duas posições."},{"en":"5 min · Explain how to recover one real length from the plan; revisit the scale next week.","pt":"5 min · Explique como recuperar uma medida real pela planta; retome a escala na próxima semana."}],"practice":[{"q":{"en":"Draw a 30 cm shelf at this scale.","pt":"Desenhe uma prateleira de 30 cm nessa escala."},"a":{"en":"Three squares long, since 3 × 10 = 30 cm.","pt":"Três quadradinhos de comprimento, pois 3 × 10 = 30 cm."}},{"q":{"en":"A side is 5 squares. What real length is it?","pt":"Um lado mede 5 quadradinhos. Qual é a medida real?"},"a":{"en":"50 cm; multiply the square count by 10 cm.","pt":"50 cm; multiplique a quantidade de quadradinhos por 10 cm."}},{"q":{"en":"Can a 50 cm by 30 cm mat fit on the model tabletop?","pt":"Um tapete de 50 cm por 30 cm cabe na mesa do modelo?"},"a":{"en":"Yes: a 5 by 3 square footprint fits within 6 by 4, with sides aligned.","pt":"Sim: 5 por 3 quadradinhos cabem em 6 por 4, com lados alinhados."}}],"observe":{"en":"Ask for the viewpoint, scale key and units before accepting a neat drawing.","pt":"Peça a vista, a legenda da escala e as unidades antes de aceitar um desenho caprichado."},"support":{"en":"Provide a prepared grid and lengths; use cut-out furniture.","pt":"Forneça grade e medidas prontas; use móveis recortados."},"extend":{"en":"Compare two arrangements and describe a route between the furniture.","pt":"Compare duas disposições e descreva um caminho entre os móveis."},"links":["../lessons/G6-15.html"],"diagram":"plan","duration":30},{"id":"P4-01","grade":4,"title":{"en":"From a round walk to an ellipse","pt":"Do passeio circular à elipse"},"gap":{"en":"Adds the missing movement-to-drawing comparison of circle and ellipse.","pt":"Acrescenta a comparação entre movimento e desenho de círculo e elipse."},"source":"S14–22","ready":{"en":"Recognise an open and a closed path; follow a boundary with a finger.","pt":"Reconhecer caminhos abertos e fechados; seguir um contorno com o dedo."},"materials":{"en":"Yarn, paper, crayons and prepared circle/ellipse outlines.","pt":"Lã, papel, giz de cera e contornos preparados de círculo e elipse."},"aim":{"en":"Compare a circle and an ellipse through direction changes and symmetry.","pt":"Comparar círculo e elipse por mudanças de direção e simetria."},"teaching":{"en":"A circle keeps a constant distance from one centre. A noncircular ellipse is longer along one axis than the other; its tighter turns occur near the ends of the long axis. An oval-looking freehand drawing is a sketch, not automatically an exact ellipse.","pt":"O círculo mantém distância constante de um centro. Uma elipse não circular é mais comprida em um eixo do que no outro; as curvas mais fechadas ficam nas pontas do eixo maior. Um desenho oval à mão livre é um esboço, não automaticamente uma elipse exata."},"flow":[{"en":"5 min · Recall straight and curved paths. Move a toy around a circular yarn loop once.","pt":"5 min · Retome caminhos retos e curvos. Mova um brinquedo uma vez pelo círculo de lã."},{"en":"15 min · Reshape the loop into a long oval. Compare where the toy changes direction slowly and where it turns more tightly. Draw the two paths freehand.","pt":"15 min · Transforme o laço em oval comprido. Compare onde a direção muda suavemente e onde a curva fica mais fechada. Desenhe os dois caminhos à mão livre."},{"en":"20 min · Use prepared mathematical circle and ellipse outlines. Fold across their centres to test matching halves. Mark the ellipse’s two axes and compare centre-to-boundary lengths.","pt":"20 min · Use contornos matemáticos preparados de círculo e elipse. Dobre pelo centro para testar metades coincidentes. Marque os dois eixos da elipse e compare distâncias do centro ao contorno."},{"en":"5 min · Describe one similarity and one difference; repeat from memory tomorrow.","pt":"5 min · Descreva uma semelhança e uma diferença; repita de memória amanhã."}],"practice":[{"q":{"en":"An ellipse has full axis lengths 12 cm and 8 cm. What are the half-axis lengths?","pt":"Uma elipse tem eixos completos de 12 cm e 8 cm. Quais são os semieixos?"},"a":{"en":"6 cm and 4 cm: halve each full length.","pt":"6 cm e 4 cm: tome a metade de cada comprimento."}},{"q":{"en":"Do all centre-to-boundary lengths match on this ellipse?","pt":"Todas as distâncias do centro ao contorno coincidem nessa elipse?"},"a":{"en":"No: 6 cm and 4 cm already give different lengths.","pt":"Não: 6 cm e 4 cm já dão comprimentos diferentes."}},{"q":{"en":"How many reflection axes does a noncircular ellipse have?","pt":"Quantos eixos de reflexão tem uma elipse não circular?"},"a":{"en":"Two, its major and minor axes. A circle has infinitely many.","pt":"Dois: o maior e o menor. Um círculo tem infinitos."}}],"observe":{"en":"Look for an explanation connecting the path, the drawing and the change of direction.","pt":"Observe uma explicação ligando percurso, desenho e mudança de direção."},"support":{"en":"Use seated finger or toy movement; use prepared outlines for fold tests.","pt":"Use movimento sentado com dedo ou brinquedo; use contornos prontos para dobrar."},"extend":{"en":"Compare a circle as the equal-axis special case, without requiring ellipse formulas.","pt":"Compare o círculo como caso de eixos iguais, sem exigir fórmulas de elipse."},"links":["P1-01.html","../lessons/G5-01.html"],"diagram":"ellipse","duration":45},{"id":"P4-02","grade":4,"title":{"en":"Triangles that change and stay triangles","pt":"Triângulos que mudam e continuam triângulos"},"gap":{"en":"Adds systematic freehand triangle variation before construction criteria.","pt":"Acrescenta variações de triângulos à mão livre antes dos critérios de construção."},"source":"S23–26","ready":{"en":"Count sides and corners; compare lengths by superposition.","pt":"Contar lados e vértices; comparar comprimentos por sobreposição."},"materials":{"en":"Three strips, paper, crayons and a folded right-angle corner.","pt":"Três tiras, papel, giz de cera e um canto reto dobrado."},"aim":{"en":"Keep the three-sided boundary while changing size, orientation and side relationships.","pt":"Manter o contorno de três lados mudando tamanho, orientação e relações entre lados."},"teaching":{"en":"A triangle has three straight sides enclosing a region. Rotating it changes neither side lengths nor angle types. Equilateral means all three sides equal; isosceles here means at least two equal, so an equilateral triangle also belongs.","pt":"Um triângulo tem três lados retos cercando uma região. Girá-lo não altera comprimentos nem tipos de ângulo. Equilátero tem três lados iguais; isósceles aqui tem pelo menos dois iguais, então inclui o equilátero."},"flow":[{"en":"5 min · Draw a triangle standing on a side, then turn the paper. Ask whether its name changes.","pt":"5 min · Desenhe um triângulo apoiado num lado e gire o papel. Pergunte se seu nome muda."},{"en":"15 min · Sketch three equal-sided triangles of increasing size. Compare side relationships rather than drawing neatness.","pt":"15 min · Esboce três triângulos equiláteros de tamanhos crescentes. Compare relações entre lados, sem avaliar o capricho."},{"en":"20 min · Hold a base fixed and move the top vertex to three positions. Make one symmetric and one right-angled example. Compare with strips and a folded corner.","pt":"20 min · Mantenha uma base fixa e mova o vértice superior para três posições. Faça um exemplo simétrico e um retângulo. Compare com tiras e um canto dobrado."},{"en":"5 min · Sort the sketches using one stated property; recall it tomorrow on a rotated triangle.","pt":"5 min · Separe os desenhos por uma propriedade declarada; retome amanhã com triângulo girado."}],"practice":[{"q":{"en":"Does a rotated equilateral triangle still have equal sides?","pt":"Um triângulo equilátero girado continua com lados iguais?"},"a":{"en":"Yes; rotation preserves all lengths.","pt":"Sim; a rotação preserva todos os comprimentos."}},{"q":{"en":"A triangle has sides 5, 5 and 6 cm. Is it equilateral?","pt":"Um triângulo tem lados 5, 5 e 6 cm. É equilátero?"},"a":{"en":"No; it is isosceles with two equal sides.","pt":"Não; é isósceles com dois lados iguais."}},{"q":{"en":"Can three points on one straight line make a triangle?","pt":"Três pontos na mesma reta formam um triângulo?"},"a":{"en":"No; the segments enclose no region.","pt":"Não; os segmentos não cercam uma região."}}],"observe":{"en":"Ask what stayed unchanged when the vertex moved; check that a rotated shape is recognised.","pt":"Pergunte o que permaneceu quando o vértice mudou; verifique o reconhecimento da forma girada."},"support":{"en":"Use large pre-cut triangles and compare by touch or tracing.","pt":"Use triângulos grandes recortados e compare pelo tato ou contorno."},"extend":{"en":"Hold base and perpendicular height fixed while shifting the vertex; save the area question for later.","pt":"Mantenha base e altura perpendicular fixas ao mover o vértice; guarde a questão da área para depois."},"links":["../lessons/G5-03.html","../lessons/G6-10.html"],"diagram":"triangles","duration":45},{"id":"P4-03","grade":4,"title":{"en":"The quadrilateral workshop","pt":"A oficina dos quadriláteros"},"gap":{"en":"Replaces a brief shape-family mention with explicit inclusive classification and symmetry tests.","pt":"Amplia a menção às famílias de formas com classificação inclusiva e testes de simetria."},"source":"S27–38","ready":{"en":"Recognise four straight sides and test a right angle.","pt":"Reconhecer quatro lados retos e testar um ângulo reto."},"materials":{"en":"Paper quadrilaterals, tracing paper and folded right-angle corner.","pt":"Quadriláteros de papel, papel vegetal e canto reto dobrado."},"aim":{"en":"Classify squares, rectangles, rhombi and parallelograms by properties, including overlapping memberships.","pt":"Classificar quadrados, retângulos, losangos e paralelogramos por propriedades, incluindo grupos que se sobrepõem."},"teaching":{"en":"A rectangle has four right angles; a rhombus has four equal sides; a parallelogram has two pairs of opposite parallel sides. A square satisfies all three definitions. A nonsquare rectangle has two reflection axes, a nonsquare rhombus two, and a square four. A generic slanted parallelogram has no reflection axis but matches after a half-turn.","pt":"Um retângulo tem quatro ângulos retos; um losango tem quatro lados iguais; um paralelogramo tem dois pares de lados opostos paralelos. Um quadrado satisfaz as três definições. Um retângulo não quadrado tem dois eixos de reflexão, um losango não quadrado dois, e um quadrado quatro. Um paralelogramo inclinado genérico não tem eixo de reflexão, mas coincide após meia-volta."},"flow":[{"en":"5 min · Recall a square’s four sides and four right angles.","pt":"5 min · Retome os quatro lados e quatro ângulos retos do quadrado."},{"en":"15 min · Sort prepared shapes under four property cards. Allow one shape to appear under several cards by tracing copies.","pt":"15 min · Separe formas com quatro cartões de propriedades. Permita que uma forma entre em vários grupos usando cópias traçadas."},{"en":"20 min · Fold copies of a square, nonsquare rectangle and nonsquare rhombus. Test diagonals and lines through side midpoints; turn a generic parallelogram halfway using tracing paper.","pt":"20 min · Dobre cópias de quadrado, retângulo não quadrado e losango não quadrado. Teste diagonais e linhas pelos pontos médios; gire um paralelogramo genérico meia-volta com papel vegetal."},{"en":"5 min · Explain why a square belongs in the rectangle group. Revisit with a tilted square next week.","pt":"5 min · Explique por que o quadrado pertence ao grupo dos retângulos. Retome com um quadrado inclinado na próxima semana."}],"practice":[{"q":{"en":"Is every square a rectangle?","pt":"Todo quadrado é retângulo?"},"a":{"en":"Yes, because it has four right angles.","pt":"Sim, pois tem quatro ângulos retos."}},{"q":{"en":"Is a 3 cm by 5 cm rectangle a rhombus?","pt":"Um retângulo de 3 cm por 5 cm é losango?"},"a":{"en":"No: its four sides are not all equal.","pt":"Não: seus quatro lados não são todos iguais."}},{"q":{"en":"Does a half-turn prove reflection symmetry?","pt":"Meia-volta demonstra simetria de reflexão?"},"a":{"en":"No. Rotation and reflection are different movements; test a fold separately.","pt":"Não. Rotação e reflexão são movimentos distintos; teste a dobra separadamente."}}],"observe":{"en":"Require a property-based reason, including an example that belongs to more than one family.","pt":"Exija uma justificativa por propriedades, incluindo um exemplo que pertence a mais de uma família."},"support":{"en":"Use prepared shapes; read property cards aloud and test by overlay.","pt":"Use formas prontas; leia os cartões em voz alta e teste por sobreposição."},"extend":{"en":"Compare a kite and an isosceles trapezoid. State whether trapezoid means exactly one or at least one parallel pair before classifying.","pt":"Compare deltoide e trapézio isósceles. Declare se trapézio significa exatamente um ou pelo menos um par de paralelas antes de classificar."},"links":["P4-02.html","../lessons/G5-03.html"],"diagram":"quads","duration":45},{"id":"P4-04","grade":4,"title":{"en":"A round ball, a changing shadow","pt":"Uma bola redonda, uma sombra que muda"},"gap":{"en":"Adds the book’s missing spatial light-and-shadow investigation.","pt":"Acrescenta a investigação espacial de luz e sombra que faltava."},"source":"S39–42","ready":{"en":"Distinguish a solid object from its flat outline; recall circle and ellipse.","pt":"Distinguir sólido de contorno plano; retomar círculo e elipse."},"materials":{"en":"Ball, stable LED torch, white card and pencil.","pt":"Bola, lanterna LED estável, cartolina branca e lápis."},"aim":{"en":"Distinguish a sphere from a disk and compare shadows when the receiving surface tilts.","pt":"Distinguir esfera de disco e comparar sombras quando a superfície receptora inclina."},"teaching":{"en":"A sphere is a three-dimensional surface; its shadow is a two-dimensional region on a receiving surface. With near-parallel light, a plane perpendicular to the beam gives a circular shadow; tilting the plane can give an elongated ellipse. A nearby torch has diverging rays: describe actual observations rather than promising an exact ellipse.","pt":"A esfera é uma superfície tridimensional; sua sombra é uma região bidimensional numa superfície receptora. Com luz quase paralela, um plano perpendicular ao feixe dá sombra circular; inclinar o plano pode dar uma elipse alongada. Uma lanterna próxima tem raios divergentes: descreva observações reais em vez de prometer elipse exata."},"flow":[{"en":"5 min · Compare a paper disk with a ball from several directions.","pt":"5 min · Compare um disco de papel com uma bola de várias direções."},{"en":"15 min · An adult positions an LED torch and ball securely. Hold the receiving card across the beam and trace the shadow. Keep the ball and light fixed.","pt":"15 min · Um adulto posiciona lanterna LED e bola com estabilidade. Segure a cartolina atravessando o feixe e trace a sombra. Mantenha bola e luz fixas."},{"en":"20 min · Tilt only the card, tracing three outlines. Record exactly what moved. Never shine light into eyes; use supplied descriptions if equipment is unavailable.","pt":"20 min · Incline apenas a cartolina e trace três contornos. Registre exatamente o que mudou. Não aponte luz para os olhos; use as descrições fornecidas se não houver equipamento."},{"en":"5 min · Explain how a round object can cast a stretched shadow. Compare the drawings again tomorrow.","pt":"5 min · Explique como um objeto redondo projeta sombra alongada. Compare os desenhos novamente amanhã."}],"practice":[{"q":{"en":"Did tilting the card change the ball’s shape?","pt":"Inclinar a cartolina mudou a forma da bola?"},"a":{"en":"No. The receiving surface changed orientation.","pt":"Não. A superfície receptora mudou de orientação."}},{"q":{"en":"Is the shadow a sphere?","pt":"A sombra é uma esfera?"},"a":{"en":"No: it is a flat region, not the three-dimensional object.","pt":"Não: é uma região plana, não o objeto tridimensional."}},{"q":{"en":"Two trials move both card and lamp. Can the difference be attributed only to card tilt?","pt":"Dois testes movem cartolina e lanterna. A diferença pode ser atribuída só à inclinação?"},"a":{"en":"No; change one condition at a time to make that comparison.","pt":"Não; mude uma condição por vez para fazer essa comparação."}}],"observe":{"en":"Listen for the distinction between object, light and receiving plane.","pt":"Observe a distinção entre objeto, luz e plano receptor."},"support":{"en":"Compare a prepared circular outline and elongated outline while someone describes the experiment.","pt":"Compare um contorno circular e outro alongado enquanto alguém descreve o experimento."},"extend":{"en":"Compare shadows cast by a disk and a ball; explain the role of orientation.","pt":"Compare sombras de disco e bola; explique o papel da orientação."},"links":["P4-01.html","../lessons/G6-12.html"],"diagram":"shadow","duration":45},{"id":"P5-01","grade":5,"title":{"en":"Two circles reveal a midpoint","pt":"Duas circunferências revelam um ponto médio"},"gap":{"en":"Connects observed symmetry to the perpendicular-bisector construction.","pt":"Liga a simetria observada à construção da mediatriz."},"source":"S50–53,64–69","ready":{"en":"Fold a reflection axis; keep a compass opening unchanged.","pt":"Dobrar um eixo de reflexão; manter a abertura do compasso."},"materials":{"en":"Paper, compass, ruler and tracing paper.","pt":"Papel, compasso, régua e papel vegetal."},"aim":{"en":"Use equal-radius circles to find a midpoint and explain their two reflection axes.","pt":"Usar circunferências de raios iguais para encontrar um ponto médio e explicar seus dois eixos de reflexão."},"teaching":{"en":"For distinct centres A and B, two equal-radius circles share reflection in line AB and in its perpendicular bisector. If the radius exceeds half AB, the two intersections C and D determine that bisector: each lies equally far from A and B. Joining C and D meets AB at its midpoint M. If the radius is too small, the circles do not intersect.","pt":"Para centros distintos A e B, duas circunferências de raios iguais têm reflexão na reta AB e em sua mediatriz. Se o raio é maior que metade de AB, as interseções C e D determinam a mediatriz: cada uma fica à mesma distância de A e B. CD encontra AB no ponto médio M. Se o raio é pequeno demais, as circunferências não se encontram."},"flow":[{"en":"5 min · Recall a fold that swaps two marked points.","pt":"5 min · Retome uma dobra que troca dois pontos marcados."},{"en":"15 min · Mark A and B 6 cm apart. With radius 4 cm draw both circles. Name their intersections C and D, then join CD and mark M on AB. Keep working arcs.","pt":"15 min · Marque A e B a 6 cm. Com raio de 4 cm, trace ambas as circunferências. Nomeie as interseções C e D, una CD e marque M em AB. Preserve os arcos."},{"en":"20 min · Fold on AB and CD to test the whole pair of circles. Measure AM and MB only after predicting equality. Repeat with the same centres and radius 5 cm.","pt":"20 min · Dobre em AB e CD para testar o par completo de circunferências. Meça AM e MB só depois de prever a igualdade. Repita com os mesmos centros e raio de 5 cm."},{"en":"5 min · Explain what changed and why the midpoint did not; repeat with new centres next week.","pt":"5 min · Explique o que mudou e por que o ponto médio não mudou; repita com novos centros na próxima semana."}],"practice":[{"q":{"en":"Find AM when AB is 6 cm.","pt":"Encontre AM quando AB mede 6 cm."},"a":{"en":"3 cm, because M divides AB into two equal parts.","pt":"3 cm, pois M divide AB em duas partes iguais."}},{"q":{"en":"Will two radius-2 cm circles with centres 6 cm apart intersect?","pt":"Duas circunferências de raio 2 cm com centros separados por 6 cm se encontram?"},"a":{"en":"No: 2 + 2 < 6. There is no C or D to join.","pt":"Não: 2 + 2 < 6. Não há C nem D para unir."}},{"q":{"en":"Why is C equally distant from A and B?","pt":"Por que C fica igualmente distante de A e B?"},"a":{"en":"CA and CB are radii of circles drawn with the same opening.","pt":"CA e CB são raios de circunferências traçadas com a mesma abertura."}}],"observe":{"en":"Check the unchanged compass opening, two intersections and an equality explanation.","pt":"Confira abertura constante, duas interseções e explicação da igualdade."},"support":{"en":"Use prepared intersecting circles and trace the two axes. Ask an adult to handle a sharp compass.","pt":"Use circunferências prontas e trace os eixos. Peça a um adulto para manusear o compasso pontiagudo."},"extend":{"en":"Compare unequal-radius circles: AB remains an axis but the perpendicular bisector generally does not.","pt":"Compare raios diferentes: AB continua eixo, mas a mediatriz em geral não."},"links":["../lessons/G6-02.html","../lessons/G6-06.html"],"diagram":"bisector","duration":45},{"id":"P5-02","grade":5,"title":{"en":"From four corners to eight","pt":"De quatro vértices a oito"},"gap":{"en":"Adds a readiness-based Grade 5 square-to-octagon construction bridge.","pt":"Acrescenta uma ponte de construção do quadrado ao octógono no 5º ano, conforme a prontidão."},"source":"S68–75","ready":{"en":"Use midpoint and angle-bisector constructions; otherwise begin with the linked Grade 6 lessons.","pt":"Usar construções de ponto médio e bissetriz; caso contrário, começar pelas aulas do 6º ano vinculadas."},"materials":{"en":"Paper, compass, straightedge and ruler for checking.","pt":"Papel, compasso, régua sem graduação e régua graduada para conferir."},"aim":{"en":"Construct a square and regular octagon in one circle; connect equal central gaps with equal sides.","pt":"Construir quadrado e octógono regular na mesma circunferência; ligar intervalos centrais iguais a lados iguais."},"teaching":{"en":"Two perpendicular diameters divide a circle into four equal 90° sectors. Their endpoints form a square. Bisecting each central angle creates eight equal 45° sectors, whose endpoints form a regular octagon. Equal gaps, not equal-looking marks, justify equal chords. A chord midpoint is inside the circle and is not a new octagon vertex.","pt":"Dois diâmetros perpendiculares dividem a circunferência em quatro setores de 90°. As extremidades formam um quadrado. Bissetar cada ângulo central cria oito setores de 45°, cujas extremidades formam um octógono regular. Intervalos iguais, não marcas parecidas, justificam cordas iguais. O ponto médio de uma corda fica dentro do círculo e não é um novo vértice do octógono."},"flow":[{"en":"5 min · Recall four quarter-turns and an equal-radius construction.","pt":"5 min · Retome quatro quartos de volta e uma construção com raios iguais."},{"en":"15 min · Draw a circle centred at O and a diameter AB. Construct its perpendicular bisector through O; mark its two intersections with the circle. Join the four boundary points in order.","pt":"15 min · Trace circunferência de centro O e diâmetro AB. Construa a mediatriz de AB passando por O; marque suas duas interseções com a circunferência. Una os quatro pontos do contorno em ordem."},{"en":"20 min · Bisect each 90° central angle: an arc centred at O marks equal distances on its rays; equal arcs from those marks meet inside the angle; join O to that intersection. Extend to the original circle. Join all eight boundary points in order.","pt":"20 min · Bissete cada ângulo central de 90°: um arco de centro O marca distâncias iguais nas semirretas; arcos iguais dessas marcas se encontram dentro do ângulo; una O à interseção. Prolongue até a circunferência original. Una os oito pontos do contorno em ordem."},{"en":"5 min · Compare side lengths as a check, then explain the equal-angle reason. Reconstruct one bisector tomorrow.","pt":"5 min · Compare os lados para conferir e explique a razão dos ângulos iguais. Reconstrua uma bissetriz amanhã."}],"practice":[{"q":{"en":"What is each octagon central angle?","pt":"Quanto mede cada ângulo central do octógono?"},"a":{"en":"360° ÷ 8 = 45°.","pt":"360° ÷ 8 = 45°."}},{"q":{"en":"Is a square-side midpoint on its circumcircle?","pt":"O ponto médio de um lado do quadrado está na circunferência circunscrita?"},"a":{"en":"No; extend the ray from the centre through it to the circle.","pt":"Não; prolongue a semirreta do centro por ele até a circunferência."}},{"q":{"en":"What regular polygon results from bisecting all eight gaps again?","pt":"Qual polígono regular resulta ao bissetar novamente os oito intervalos?"},"a":{"en":"A 16-sided polygon with central angles 22.5°.","pt":"Um polígono de 16 lados com ângulos centrais de 22,5°."}}],"observe":{"en":"Look for boundary vertices and retained construction arcs; do not infer accuracy from decoration.","pt":"Observe vértices no contorno e arcos preservados; não deduza precisão pela decoração."},"support":{"en":"Provide the square and work on one bisector; use the existing step-by-step bisector lesson.","pt":"Forneça o quadrado e trabalhe uma bissetriz; use a aula de bissetriz passo a passo."},"extend":{"en":"Add alternate-vertex connections and state which polygon they form.","pt":"Ligue vértices alternados e diga qual polígono formam."},"links":["P5-01.html","../lessons/G6-08.html","../lessons/G6-09.html"],"diagram":"octagon","duration":45},{"id":"P5-03","grade":5,"title":{"en":"Squares nested by their midpoints","pt":"Quadrados encaixados pelos pontos médios"},"gap":{"en":"Adds a geometric art sequence with an explicit area relationship.","pt":"Acrescenta uma sequência de arte geométrica com relação explícita de áreas."},"source":"S54–56,68–69","ready":{"en":"Identify a midpoint and count square units.","pt":"Identificar ponto médio e contar unidades quadradas."},"materials":{"en":"Squared paper, ruler, compass or folded midpoint marks, crayons.","pt":"Papel quadriculado, régua, compasso ou pontos médios por dobra, giz de cera."},"aim":{"en":"Connect side midpoints to form a new square and compare successive areas.","pt":"Ligar pontos médios para formar outro quadrado e comparar áreas sucessivas."},"teaching":{"en":"In an 8 cm square, joining side midpoints removes four corner right triangles, each with legs 4 cm and area 8 cm². The inner square has area 64 − 32 = 32 cm². Its tilted position does not change its being a square. Each repeated midpoint square halves the area, not the side length.","pt":"Num quadrado de 8 cm, unir pontos médios remove quatro triângulos retângulos, cada um com catetos de 4 cm e área de 8 cm². O quadrado interno tem área 64 − 32 = 32 cm². A inclinação não deixa de torná-lo quadrado. Cada novo quadrado de pontos médios reduz a área à metade, não o lado."},"flow":[{"en":"5 min · Recall the area of an 8 by 8 square and the meaning of midpoint.","pt":"5 min · Retome a área de um quadrado de 8 por 8 e o significado de ponto médio."},{"en":"15 min · Draw the outer square; find four side midpoints by fold, construction or grid count. Join them in cyclic order. Test equal sides and right angles.","pt":"15 min · Desenhe o quadrado externo; encontre quatro pontos médios por dobra, construção ou contagem. Una-os em ordem. Teste lados iguais e ângulos retos."},{"en":"20 min · Cut or trace four corner triangles. Pair them into two 4 by 4 squares to compare removed and remaining area. Repeat the midpoint step twice and record areas.","pt":"20 min · Recorte ou trace os quatro triângulos dos cantos. Junte-os em dois quadrados de 4 por 4 para comparar área removida e restante. Repita o passo dos pontos médios duas vezes e registre áreas."},{"en":"5 min · Explain why area halves. Next week, predict before drawing in a different-sized square.","pt":"5 min · Explique por que a área cai à metade. Na próxima semana, preveja antes de desenhar em outro quadrado."}],"practice":[{"q":{"en":"Give the first three inner areas when the outer area is 64 cm².","pt":"Dê as três primeiras áreas internas quando a externa é 64 cm²."},"a":{"en":"32, 16 and 8 cm²; halve each previous area.","pt":"32, 16 e 8 cm²; tome metade da área anterior."}},{"q":{"en":"Would halving an 8 cm side produce half the area?","pt":"Reduzir um lado de 8 cm à metade produz metade da área?"},"a":{"en":"No: a 4 cm square has 16 cm², one quarter of 64 cm².","pt":"Não: um quadrado de 4 cm tem 16 cm², um quarto de 64 cm²."}},{"q":{"en":"An outer square has area 100 cm². Predict its first midpoint-square area.","pt":"Um quadrado externo tem área de 100 cm². Preveja a área do primeiro quadrado dos pontos médios."},"a":{"en":"50 cm² by the same four-corner rearrangement.","pt":"50 cm² pelo mesmo rearranjo dos quatro cantos."}}],"observe":{"en":"Ask for a cut-and-match reason and distinguish side scale from area scale.","pt":"Peça justificativa por recorte e distinga escala de lado da de área."},"support":{"en":"Use a prepared grid and pre-cut triangles; postpone formulas until the pieces match.","pt":"Use grade pronta e triângulos recortados; adie fórmulas até as peças coincidirem."},"extend":{"en":"Compare perimeters: each new side is the old side divided by √2; treat this as optional later work.","pt":"Compare perímetros: cada lado novo é o anterior dividido por √2; trate como extensão posterior opcional."},"links":["P4-03.html","../lessons/G7-06.html"],"diagram":"nested","duration":45},{"id":"P5-04","grade":5,"title":{"en":"Double a square without doubling its side","pt":"Dobre a área do quadrado sem dobrar o lado"},"gap":{"en":"Adds an experiential diagonal-square bridge before the general Pythagorean theorem.","pt":"Acrescenta uma ponte vivencial pelo quadrado da diagonal antes do teorema geral de Pitágoras."},"source":"S82–84","ready":{"en":"Count square units; identify a square and a diagonal.","pt":"Contar unidades quadradas; identificar quadrado e diagonal."},"materials":{"en":"Grid paper, four congruent right-isosceles triangles, tape.","pt":"Papel quadriculado, quatro triângulos retângulos isósceles congruentes, fita."},"aim":{"en":"Build a square on a diagonal and justify its doubled area using equal pieces.","pt":"Construir um quadrado sobre uma diagonal e justificar o dobro da área com peças iguais."},"teaching":{"en":"Cut two 4 cm squares along one diagonal each. The four equal right-isosceles triangles each have area 8 cm². Place their right-angle vertices together at one centre; their hypotenuses bound a larger square. Its area is 4 × 8 = 32 cm², twice 16 cm². This special case prepares for a later general theorem; it is not a proof for every right triangle.","pt":"Corte dois quadrados de 4 cm por uma diagonal cada. Os quatro triângulos retângulos isósceles têm área de 8 cm² cada. Junte seus vértices de ângulo reto num centro; as hipotenusas delimitam um quadrado maior. Sua área é 4 × 8 = 32 cm², o dobro de 16 cm². Esse caso prepara um teorema geral posterior; não demonstra todos os triângulos retângulos."},"flow":[{"en":"5 min · Predict how to make a square of twice the area. Record the tempting doubled-side guess.","pt":"5 min · Preveja como fazer um quadrado com o dobro da área. Registre a hipótese de dobrar o lado."},{"en":"15 min · Make two 4 by 4 squares and cut along one diagonal in each. Label the four equal pieces and compare their areas.","pt":"15 min · Faça dois quadrados de 4 por 4 e corte uma diagonal de cada. Identifique as quatro peças iguais e compare suas áreas."},{"en":"20 min · Arrange the four right-angle corners around one centre, with 4 cm legs touching. Check no gap or overlap. Trace the outside square and compare with one original square and an 8 by 8 square.","pt":"20 min · Junte os quatro ângulos retos num centro, com catetos de 4 cm encostados. Confira ausência de lacunas ou sobreposição. Trace o quadrado externo e compare com um original e um de 8 por 8."},{"en":"5 min · Explain why doubling the side fails; repeat the reasoning next week with a 3 cm square.","pt":"5 min · Explique por que dobrar o lado não funciona; repita o raciocínio na próxima semana com um quadrado de 3 cm."}],"practice":[{"q":{"en":"What area doubles 16 cm²?","pt":"Qual área é o dobro de 16 cm²?"},"a":{"en":"32 cm²; four triangles of 8 cm² fill it.","pt":"32 cm²; quatro triângulos de 8 cm² a preenchem."}},{"q":{"en":"What area has a square with side 8 cm?","pt":"Qual é a área de um quadrado de lado 8 cm?"},"a":{"en":"64 cm², four times the 4 cm square’s area.","pt":"64 cm², quatro vezes a área do quadrado de 4 cm."}},{"q":{"en":"A square has side 3 cm. What is the area of the square on its diagonal?","pt":"Um quadrado tem lado 3 cm. Qual é a área do quadrado sobre sua diagonal?"},"a":{"en":"18 cm²: twice 3 × 3 = 9 cm².","pt":"18 cm²: o dobro de 3 × 3 = 9 cm²."}}],"observe":{"en":"Check conservation of the four pieces and a spoken comparison of areas.","pt":"Confira conservação das quatro peças e comparação oral das áreas."},"support":{"en":"Provide pre-cut pieces; let the learner direct a partner’s arrangement.","pt":"Forneça peças recortadas; deixe o estudante orientar a montagem de outra pessoa."},"extend":{"en":"Later, connect the side length 4√2 cm with 4² + 4²; keep the area experience first.","pt":"Depois, ligue o lado de 4√2 cm a 4² + 4²; mantenha primeiro a experiência de áreas."},"links":["P5-03.html","../lessons/G7-08.html","../lessons/G7-09.html"],"diagram":"double","duration":45},{"id":"P6-01","grade":6,"title":{"en":"Copy an angle and explain a parallel","pt":"Copie um ângulo e explique uma paralela"},"gap":{"en":"Deepens parallel construction with an explicit angle-transfer procedure.","pt":"Aprofunda a construção de paralelas com procedimento explícito de transferência de ângulo."},"source":"S77–79","ready":{"en":"Use a compass to transfer distances; name angle vertices and rays.","pt":"Usar compasso para transferir distâncias; nomear vértices e semirretas."},"materials":{"en":"Compass, straightedge, paper and protractor for checking.","pt":"Compasso, régua sem graduação, papel e transferidor para conferir."},"aim":{"en":"Copy an angle by transferring an arc radius and chord; explain how corresponding angles construct a parallel.","pt":"Copiar um ângulo transferindo raio de arco e corda; explicar como ângulos correspondentes constroem uma paralela."},"teaching":{"en":"To copy ∠AOB at P on a chosen ray, draw equal-radius arcs centred at O and P. The first arc meets OA and OB at U and V; the second meets the given ray at U′. Copy chord UV with centre U′ to meet the second arc at V′. Ray PV′ completes an equal angle: triangles OUV and PU′V′ have three matching sides. Choose the intended side of the ray.","pt":"Para copiar ∠AOB em P numa semirreta escolhida, trace arcos de raios iguais com centros O e P. O primeiro encontra OA e OB em U e V; o segundo encontra a semirreta em U′. Copie a corda UV com centro U′ para encontrar o segundo arco em V′. PV′ completa ângulo igual: os triângulos OUV e PU′V′ têm três lados correspondentes iguais. Escolha o lado pretendido da semirreta."},"flow":[{"en":"5 min · Recall how a compass transfers length and why a protractor checks rather than constructs an exact copy.","pt":"5 min · Retome a transferência de comprimento e por que o transferidor confere, em vez de construir, uma cópia exata."},{"en":"15 min · Draw any acute angle and copy it at P using the two arcs and chord. Label O,U,V,P,U′,V′. Measure both angles afterwards.","pt":"15 min · Desenhe um ângulo agudo e copie-o em P com dois arcos e uma corda. Identifique O,U,V,P,U′,V′. Meça ambos depois."},{"en":"20 min · Draw line l, point P off it and Q on l. Extend QP beyond P. Copy at P the angle between the ray QP and a ray along l, using the ray beyond P as the new starting ray. Choose the matching corresponding-angle side; extend the new ray into a line.","pt":"20 min · Trace reta l, ponto P fora dela e Q em l. Prolongue QP além de P. Copie em P o ângulo entre QP e uma semirreta de l, usando a semirreta além de P como origem da cópia. Escolha o lado do ângulo correspondente; prolongue a nova semirreta em reta."},{"en":"5 min · Explain why equal corresponding angles imply parallel lines. Repeat with an obtuse angle next week.","pt":"5 min · Explique por que ângulos correspondentes iguais implicam paralelas. Repita com um ângulo obtuso na próxima semana."}],"practice":[{"q":{"en":"What two compass distances must be copied?","pt":"Quais duas distâncias do compasso devem ser copiadas?"},"a":{"en":"The arc radius and the chord between the angle rays.","pt":"O raio do arco e a corda entre as semirretas do ângulo."}},{"q":{"en":"If the original angle is 58°, what should its copy measure?","pt":"Se o ângulo original mede 58°, quanto deve medir a cópia?"},"a":{"en":"58°; drawing error can affect the measured check.","pt":"58°; erros de desenho podem afetar a conferência."}},{"q":{"en":"Is equal-looking slope sufficient justification?","pt":"Inclinação aparentemente igual basta como justificativa?"},"a":{"en":"No; state the equal corresponding angles and their transversal.","pt":"Não; declare os ângulos correspondentes iguais e sua transversal."}}],"observe":{"en":"Inspect copied radii and chord and ask the learner to identify the corresponding-angle pair.","pt":"Inspecione raios e corda copiados e peça que identifique os ângulos correspondentes."},"support":{"en":"Begin with angle copying alone; provide labelled arcs and choose between two candidate copies.","pt":"Comece só pela cópia do ângulo; forneça arcos identificados e escolha entre duas cópias candidatas."},"extend":{"en":"Explain the equality using three equal sides; distinguish copying from bisecting.","pt":"Explique a igualdade usando três lados iguais; distinga copiar de bissetar."},"links":["../lessons/G6-07.html","../lessons/G6-08.html"],"diagram":"parallel","duration":45},{"id":"P6-02","grade":6,"title":{"en":"The path halfway between two lines","pt":"O caminho a meio entre duas retas"},"gap":{"en":"Adds the missing middle-parallel construction and its equal-distance condition.","pt":"Acrescenta a construção da paralela média e a condição de equidistância."},"source":"S79–80","ready":{"en":"Construct a midpoint and a parallel through a point.","pt":"Construir ponto médio e paralela por um ponto."},"materials":{"en":"Paper, straightedge, compass and set square for checking.","pt":"Papel, régua sem graduação, compasso e esquadro para conferir."},"aim":{"en":"Construct the unique line halfway between two distinct parallel lines; measure perpendicular distance.","pt":"Construir a reta única a meio entre duas paralelas distintas; medir distância perpendicular."},"teaching":{"en":"Intersect the parallel lines with any transversal at A and B. Construct midpoint M of AB. A parallel through M lies halfway between the originals, even if AB is slanted. Distance between parallel lines is measured perpendicularly; a slanted segment across the strip is longer than that distance.","pt":"Corte as paralelas com qualquer transversal em A e B. Construa o ponto médio M de AB. A paralela por M fica a meio entre as originais, mesmo com AB inclinado. A distância entre paralelas é medida perpendicularmente; um segmento inclinado atravessando a faixa é maior que essa distância."},"flow":[{"en":"5 min · Recall the difference between a midpoint and a perpendicular foot.","pt":"5 min · Retome a diferença entre ponto médio e pé de perpendicular."},{"en":"15 min · Draw two parallel lines and an oblique crossing segment AB. Construct M with equal-radius arcs. Construct a parallel through M using the preceding angle-transfer lesson.","pt":"15 min · Trace duas paralelas e um segmento transversal inclinado AB. Construa M com arcos iguais. Construa uma paralela por M usando a aula anterior de transferência de ângulo."},{"en":"20 min · Draw a second transversal elsewhere and find its midpoint N. Check that N lies on the constructed middle line. Use a perpendicular to compare the two strip widths.","pt":"20 min · Trace outra transversal e ache seu ponto médio N. Confira se N está na paralela média. Use uma perpendicular para comparar as larguras das duas faixas."},{"en":"5 min · Explain why a slanted crossing length is not the strip width; retrieve the construction next week.","pt":"5 min · Explique por que o comprimento inclinado não é a largura; retome a construção na próxima semana."}],"practice":[{"q":{"en":"Two parallel boundaries are 8 cm apart. How far is the middle parallel from each?","pt":"Duas paralelas estão separadas por 8 cm. A que distância fica a paralela média de cada uma?"},"a":{"en":"4 cm, measured perpendicularly.","pt":"4 cm, medidos perpendicularmente."}},{"q":{"en":"An oblique segment AB is 10 cm. What is AM?","pt":"Um segmento inclinado AB mede 10 cm. Quanto mede AM?"},"a":{"en":"5 cm along that transversal; this does not establish the perpendicular strip width.","pt":"5 cm nessa transversal; isso não determina a largura perpendicular da faixa."}},{"q":{"en":"Can the same construction define a constant-width middle strip for intersecting lines?","pt":"A mesma construção define faixa média de largura constante entre retas concorrentes?"},"a":{"en":"No; intersecting lines do not have constant separation. Their angle bisectors form a different equal-distance locus.","pt":"Não; concorrentes não têm separação constante. Suas bissetrizes formam outro lugar de equidistância."}}],"observe":{"en":"Check both the midpoint construction and the perpendicular-distance explanation.","pt":"Confira construção do ponto médio e explicação da distância perpendicular."},"support":{"en":"Start with a perpendicular transversal and prepared parallels, then try an oblique one.","pt":"Comece com transversal perpendicular e paralelas prontas; depois tente uma inclinada."},"extend":{"en":"Divide the strip into four equal-width bands by repeating the midpoint construction.","pt":"Divida a faixa em quatro larguras iguais repetindo a construção."},"links":["P5-01.html","P6-01.html"],"diagram":"parallel","duration":45},{"id":"P7-01","grade":7,"title":{"en":"When a quadrilateral fits a circle","pt":"Quando um quadrilátero cabe numa circunferência"},"gap":{"en":"Adds the cyclic-quadrilateral extension anticipated in Schuberth’s Grade 4 discussion.","pt":"Acrescenta a extensão de quadriláteros cíclicos prevista na discussão do 4º ano de Schuberth."},"source":"S33","ready":{"en":"Use perpendicular bisectors, triangle-angle sums and the inscribed-angle relationship, introduced here.","pt":"Usar mediatrizes, soma dos ângulos triangulares e relação do ângulo inscrito, introduzida aqui."},"materials":{"en":"Compass, straightedge, tracing paper and protractor.","pt":"Compasso, régua sem graduação, papel vegetal e transferidor."},"aim":{"en":"Construct a circle through three noncollinear points and test a fourth; explain opposite-angle sums.","pt":"Construir circunferência por três pontos não colineares e testar um quarto; explicar a soma de ângulos opostos."},"teaching":{"en":"A cyclic quadrilateral has all four vertices on one circle. Find the centre through perpendicular bisectors of AB and BC; their intersection is equally distant from A,B,C. A fourth point D need not lie on that circle. For a convex cyclic quadrilateral, opposite interior angles sum to 180°: each is half its intercepted arc, and those two arcs make 360°. The inscribed-angle fact follows by joining the centre to the angle’s endpoints and vertex, then using the resulting isosceles triangles and triangle-angle sums.","pt":"Um quadrilátero cíclico tem os quatro vértices na mesma circunferência. Ache o centro pelas mediatrizes de AB e BC; a interseção é equidistante de A,B,C. Um quarto ponto D pode não pertencer à circunferência. Num quadrilátero convexo cíclico, ângulos internos opostos somam 180°: cada um vale metade do arco que intercepta e esses arcos completam 360°. A relação do ângulo inscrito decorre de ligar o centro às extremidades e ao vértice do ângulo, usando os triângulos isósceles e a soma de ângulos."},"flow":[{"en":"5 min · Recall that a rectangle’s diagonals meet at equal distances from all four corners.","pt":"5 min · Retome que as diagonais de um retângulo se encontram a distâncias iguais dos quatro vértices."},{"en":"15 min · Mark noncollinear A,B,C and construct two perpendicular bisectors. Draw the circle through them. Choose D on the remaining arc to make a convex quadrilateral.","pt":"15 min · Marque A,B,C não colineares e construa duas mediatrizes. Trace a circunferência por eles. Escolha D no arco restante para fazer quadrilátero convexo."},{"en":"20 min · Measure opposite angles and record sums. Draw the two intercepted arcs in different colours. Explain the half-arc relation; move D off the circle and test again.","pt":"20 min · Meça ângulos opostos e registre somas. Destaque os dois arcos interceptados com cores diferentes. Explique a relação de meio arco; mova D para fora da circunferência e teste novamente."},{"en":"5 min · Separate measurement evidence from the general arc argument. Revisit the argument next week with a rotated figure.","pt":"5 min · Separe evidência medida do argumento geral dos arcos. Retome na próxima semana com figura girada."}],"practice":[{"q":{"en":"One opposite angle is 112°. Find the other for a convex cyclic quadrilateral.","pt":"Um ângulo oposto mede 112°. Ache o outro num quadrilátero convexo cíclico."},"a":{"en":"68°, because 180° − 112° = 68°.","pt":"68°, pois 180° − 112° = 68°."}},{"q":{"en":"Is every rectangle cyclic?","pt":"Todo retângulo é cíclico?"},"a":{"en":"Yes. Its diagonal intersection is equally far from all four vertices.","pt":"Sim. A interseção das diagonais é equidistante dos quatro vértices."}},{"q":{"en":"Can a nonsquare rhombus be cyclic?","pt":"Um losango não quadrado pode ser cíclico?"},"a":{"en":"No. Its opposite angles are equal; if supplementary, each would be 90°, making it a square.","pt":"Não. Seus ângulos opostos são iguais; se suplementares, cada um seria 90°, tornando-o quadrado."}}],"observe":{"en":"Check the fourth point rather than assuming every quadrilateral has a circumcircle. Accept arc reasoning only once its prerequisite is understood.","pt":"Confira o quarto ponto sem presumir circunferência para todo quadrilátero. Aceite o argumento dos arcos só quando o pré-requisito estiver compreendido."},"support":{"en":"Use a rectangle first; treat the general angle theorem as a teacher-guided extension if needed.","pt":"Comece com retângulo; trate o teorema angular geral como extensão orientada se necessário."},"extend":{"en":"Prove the inscribed-angle fact first when the centre lies on an angle ray, then split a general angle into those cases.","pt":"Demonstre primeiro a relação do ângulo inscrito com centro numa semirreta do ângulo; depois decomponha o caso geral."},"links":["P4-03.html","../lessons/G7-02.html","../lessons/G7-13.html"],"diagram":"cyclic","duration":45},{"id":"P8-01","grade":8,"title":{"en":"A quadrilateral around a circle","pt":"Um quadrilátero ao redor de um círculo"},"gap":{"en":"Adds tangential quadrilaterals and a necessary length check, complementing cyclic figures.","pt":"Acrescenta quadriláteros tangenciais e uma condição necessária de comprimentos, complementando figuras cíclicas."},"source":"S33","ready":{"en":"Know perpendicular radius/tangent relationship and congruent right triangles; review with the teacher.","pt":"Conhecer a perpendicularidade entre raio e tangente e triângulos retângulos congruentes; revisar com docente."},"materials":{"en":"Compass, straightedge, set square, paper.","pt":"Compasso, régua sem graduação, esquadro, papel."},"aim":{"en":"Build a quadrilateral with an incircle and justify equal tangent lengths from each vertex.","pt":"Construir quadrilátero com círculo inscrito e justificar tangentes iguais de cada vértice."},"teaching":{"en":"A tangential quadrilateral has a circle touching all four sides. A tangent is perpendicular to the radius at contact. From an external vertex, the two tangent segments to the same circle have equal lengths: the right triangles share the centre-to-vertex hypotenuse and have equal radii. If vertex tangent lengths are x,y,z,w in order, the sides are x+y,y+z,z+w,w+x, so opposite side sums agree. Treat that equality as a necessary check; do not claim a measured equality alone proves an incircle.","pt":"Um quadrilátero tangencial tem um círculo tocando seus quatro lados. A tangente é perpendicular ao raio no contato. De um vértice externo, os dois segmentos tangentes à mesma circunferência são iguais: os triângulos retângulos têm hipotenusa comum do centro ao vértice e raios iguais. Se os comprimentos tangentes dos vértices são x,y,z,w em ordem, os lados são x+y,y+z,z+w,w+x, logo as somas dos lados opostos coincidem. Trate a igualdade como condição necessária; uma igualdade medida sozinha não demonstra círculo inscrito."},"flow":[{"en":"5 min · Distinguish vertices on a circle from sides touching a circle.","pt":"5 min · Distinga vértices na circunferência de lados tangenciando a circunferência."},{"en":"15 min · Draw a circle and four contact points around it, with no angular gap of 180° or more. At each contact construct a perpendicular to its radius. Adjacent tangents meet to enclose the circle; adjust contact choices if necessary.","pt":"15 min · Trace circunferência e quatro contatos ao redor, sem intervalo angular de 180° ou mais. Construa em cada contato uma perpendicular ao raio. Tangentes vizinhas se encontram cercando o círculo; ajuste os contatos se necessário."},{"en":"20 min · Label vertices A,B,C,D and contact points. Mark each pair of equal tangent segments and derive AB+CD=BC+DA before measuring.","pt":"20 min · Identifique vértices A,B,C,D e contatos. Marque pares de tangentes iguais e deduza AB+CD=BC+DA antes de medir."},{"en":"5 min · Explain the difference from a cyclic quadrilateral. Retrieve the tangent-pair reason next week.","pt":"5 min · Explique a diferença para um quadrilátero cíclico. Retome a razão das tangentes iguais na próxima semana."}],"practice":[{"q":{"en":"AB=7, BC=6 and CD=5 cm. Find DA if the quadrilateral is tangential.","pt":"AB=7, BC=6 e CD=5 cm. Ache DA se o quadrilátero é tangencial."},"a":{"en":"7 + 5 = 6 + DA, so DA = 6 cm.","pt":"7 + 5 = 6 + DA, portanto DA = 6 cm."}},{"q":{"en":"Can a 4 cm by 6 cm rectangle have a circle tangent to all four sides?","pt":"Um retângulo de 4 cm por 6 cm pode ter círculo tangente aos quatro lados?"},"a":{"en":"No. Opposite sums are 8 and 12 cm; a circle cannot have both diameters 4 and 6 cm.","pt":"Não. As somas opostas são 8 e 12 cm; um círculo não pode ter diâmetros de 4 e 6 cm."}},{"q":{"en":"A square has side 8 cm. Find its incircle radius.","pt":"Um quadrado tem lado 8 cm. Ache o raio do círculo inscrito."},"a":{"en":"4 cm, half the separation of opposite sides.","pt":"4 cm, metade da distância entre lados opostos."}}],"observe":{"en":"Require tangent contact, perpendicular radii and equal-length pairs in the explanation.","pt":"Exija contato tangente, raios perpendiculares e pares iguais na explicação."},"support":{"en":"Begin with a square and its incircle; use prepared tangent lines to compare a more general shape.","pt":"Comece com quadrado e círculo inscrito; use tangentes prontas para comparar forma mais geral."},"extend":{"en":"Compare a square, which is both cyclic and tangential, with a nonsquare rectangle, which is only cyclic.","pt":"Compare quadrado, que é cíclico e tangencial, com retângulo não quadrado, que é apenas cíclico."},"links":["P7-01.html","../lessons/G8-01.html"],"diagram":"tangent","duration":45},{"id":"P8-02","grade":8,"title":{"en":"A room drawn toward a vanishing point","pt":"Um quarto desenhado para um ponto de fuga"},"gap":{"en":"Expands the existing brief perspective extension into a teachable project.","pt":"Amplia a breve extensão de perspectiva existente para um projeto de ensino."},"source":"J8","ready":{"en":"Distinguish a plan from a front view; recognise parallel lines and scale.","pt":"Distinguir planta de vista frontal; reconhecer paralelas e escala."},"materials":{"en":"Paper, pencil, straightedge and a simple box or room photograph.","pt":"Papel, lápis, régua sem graduação e uma caixa simples ou foto de quarto."},"aim":{"en":"Construct a one-point perspective interior and distinguish apparent convergence from physical parallelism.","pt":"Construir um interior em perspectiva de um ponto e distinguir convergência aparente de paralelismo físico."},"teaching":{"en":"In one-point perspective for a room viewed straight toward its back wall, horizontal and vertical edges of that wall stay horizontal and vertical in the picture. Edges perpendicular to that wall converge to one vanishing point on the horizon. Equal real depth intervals generally appear shorter farther away; equal paper spacing is not evidence of equal real depth. Perspective drawing is a projection, not a scale plan for measuring every length.","pt":"Na perspectiva de um ponto de um quarto visto de frente para a parede do fundo, as arestas horizontais e verticais dessa parede mantêm essas direções na imagem. Arestas perpendiculares a ela convergem a um ponto de fuga no horizonte. Intervalos reais iguais de profundidade geralmente parecem menores ao longe; espaçamento igual no papel não indica profundidade real igual. Perspectiva é projeção, não planta em escala para medir qualquer comprimento."},"flow":[{"en":"5 min · Compare the top-view reading-corner plan with a front view. Identify what each makes visible.","pt":"5 min · Compare a planta do canto de leitura com vista frontal. Identifique o que cada uma mostra."},{"en":"15 min · Draw a back-wall rectangle, a horizon through it and a vanishing point on that horizon. Extend rays from the vanishing point through the four corners to establish floor, ceiling and side walls.","pt":"15 min · Desenhe o retângulo da parede do fundo, horizonte por ele e ponto de fuga nesse horizonte. Prolongue semirretas do ponto de fuga pelos quatro vértices para estabelecer piso, teto e paredes laterais."},{"en":"20 min · Add a doorway on a side wall. Its vertical edges stay vertical and its receding top and bottom edges aim at the same vanishing point. Trace each line family in a different colour and compare with a box.","pt":"20 min · Acrescente uma porta na parede lateral. Suas arestas verticais ficam verticais e as bordas superior e inferior em profundidade apontam ao mesmo ponto de fuga. Destaque famílias de linhas com cores distintas e compare com uma caixa."},{"en":"5 min · Explain why real parallel edges can meet in the drawing. Next week, redraw with a higher horizon and compare eye level.","pt":"5 min · Explique por que arestas reais paralelas se encontram no desenho. Na próxima semana, redesenhe com horizonte mais alto e compare a altura do olhar."}],"practice":[{"q":{"en":"Should every edge in the picture aim at the vanishing point?","pt":"Toda aresta da imagem deve apontar ao ponto de fuga?"},"a":{"en":"No. Only the depth-direction family in this one-point setup; front-facing vertical and horizontal edges keep their directions.","pt":"Não. Apenas a família em profundidade nesse modelo; arestas frontais verticais e horizontais mantêm as direções."}},{"q":{"en":"Two floor tiles look different in depth. Must their real lengths differ?","pt":"Dois ladrilhos parecem diferentes em profundidade. Seus comprimentos reais precisam ser distintos?"},"a":{"en":"No. Projection makes equal lengths appear different at different distances.","pt":"Não. A projeção faz comprimentos iguais parecerem distintos a distâncias diferentes."}},{"q":{"en":"Which drawing should guide a measured floor layout: a declared-scale plan or this perspective sketch?","pt":"Qual desenho deve orientar um piso medido: planta com escala ou este esboço em perspectiva?"},"a":{"en":"The scale plan; perspective helps visualise space but has no single length scale throughout.","pt":"A planta em escala; a perspectiva ajuda a visualizar, mas não tem escala única de comprimento em toda parte."}}],"observe":{"en":"Check one common vanishing point for the depth edges and an explanation of what the drawing preserves.","pt":"Confira um ponto de fuga comum às arestas em profundidade e uma explicação do que o desenho preserva."},"support":{"en":"Provide the back wall, horizon and rays; let the learner identify line families aloud or by tracing.","pt":"Forneça parede, horizonte e semirretas; identifique famílias oralmente ou traçando."},"extend":{"en":"Move the vanishing point left or right on the horizon; compare the apparent room without claiming exact measurements.","pt":"Mova o ponto de fuga no horizonte; compare a aparência do quarto sem afirmar medidas exatas."},"links":["P3-01.html","../lessons/G8-12.html"],"diagram":"perspective","duration":45}];
